args.code:
T0 = None
PHASE = 'fwd'

def control(obs):
    global T0, PHASE
    t = obs['t']
    h = obs['hitch_deg']
    if T0 is None:
        T0 = t
    if PHASE == 'fwd':
        if t - T0 < 2.5:
            return (0.0, 0.8, 0)
        PHASE = 'rev'
    s = max(-15.0, min(15.0, 2.0 * h))
    return (s, -0.6, 180)

